<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/css/design.css"><title>Support</title></head><body class="dashboard-page"><header class="dashboard-header"><a href="/">SUN SON SOLAR</a><span><?= esc(session()->get('name')) ?></span><a href="/logout">Logout</a></header><main class="section"><h1>Support Tickets</h1><div class="card"><form method="post" action="/customer/support"><?= csrf_field() ?><label>Subject</label><input name="subject" required><label>Message</label><textarea name="message" required></textarea><button class="button primary">Send Ticket</button></form></div><div class="card"><?php foreach($tickets as $t):?><p><strong><?= esc($t['subject']) ?></strong> · <?= esc($t['status']) ?><br><?= esc($t['message']) ?></p><?php endforeach;?></div></main><script src="/js/main.js"></script></body></html>